SYSCTL_CONF = "/etc/sysctl.conf"
BACKUP_CONF = "/etc/sysctl.conf.backup"

SETTINGS = {
    "net.ipv4.ip_forward": "1",
    "net.ipv6.conf.all.disable_ipv6": "0",
    "net.ipv6.conf.default.disable_ipv6": "0",
    "net.ipv6.conf.all.forwarding": "1",
}


def backup_sysctl():
    if not os.path.exists(BACKUP_CONF):
        shutil.copy(SYSCTL_CONF, BACKUP_CONF)
        print(f"\033[93mBackup created at {BACKUP_CONF}\033[0m")
    else:
        print(f"\033[92mBackup already exists at {BACKUP_CONF}\033[0m")


def apply():
    with open(SYSCTL_CONF, "r") as file:
        lines = file.readlines()

    current_settings = {}
    for line in lines:
        if "=" in line:
            key, value = line.strip().split("=", 1)
            current_settings[key.strip()] = value.strip()

    with open(SYSCTL_CONF, "a") as file:
        for key, value in SETTINGS.items():
            if current_settings.get(key) != value:
                file.write(f"{key} = {value}\n")
                subprocess.run(["sysctl", "-w", f"{key}={value}"])
                print(f"\033[92mApplied \033[94m{key} \033[93m= \033[94m{value}\033[0m")
            else:
                print(f"\033[94m{key}\033[93m is already set to {value}\033[0m")


def restore_backup():
    if os.path.exists(BACKUP_CONF):
        shutil.copy(BACKUP_CONF, SYSCTL_CONF)
        subprocess.run(["sysctl", "-p"])
        print(f"\033[93mRestored configuration from {BACKUP_CONF}\033[0m")
    else:
        print(f"\033[91mNo backup found at {BACKUP_CONF}\033[0m")


def display_progress(total, current):
    width = 40
    percentage = current * 100 // total
    completed = width * current // total
    remaining = width - completed

    print(
        "\r[" + "=" * completed + ">" + " " * remaining + "] %d%%" % percentage, end=""
    )


def display_checkmark(message):
    print("\u2714 " + message)


def display_error(message):
    print("\u2718 Error: " + message)


def display_notification(message):
    print("\u2728 " + message)


def display_loading():
    frames = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]
    delay = 0.1
    duration = 5

    end_time = time.time() + duration

    while time.time() < end_time:
        for frame in frames:
            print("\r[" + frame + "] Loading...  ", end="")
            time.sleep(delay)
            print("\r[" + frame + "]             ", end="")
            time.sleep(delay)

