def update_sysctl():
    os.system("clear")
    print("\033[92m ^ ^\033[0m")
    print("\033[92m(\033[91mO,O\033[92m)\033[0m")
    print("\033[92m(   ) \033[93mEnable IPV4/6 Forward Menu\033[0m")
    print('\033[92m "-"\033[93m═════════════════════════════════════════\033[0m')
    print("\033[93m╭───────────────────────────────────────╮\033[0m")
    print("\033[93mChoose what to do:\033[0m")
    print("1. \033[92mApply Stuff\033[0m")
    print("2. \033[93mRestore Stuff\033[0m")
    print("0.\033[94mback to the main menu\033[0m")
    print("\033[93m╰───────────────────────────────────────╯\033[0m")

    while True:
        server_type = input("\033[38;5;205mEnter your choice Please: \033[0m")
        if server_type == "1":
            backup_sysctl()
            apply()
            break
        elif server_type == "2":
            restore_backup()
            break
        elif server_type == "0":
            os.system("clear")
            main_menu()
            break
        else:
            print("Invalid choice.")


