def reset_ping_ipip6kharej1():
    script_content = f"""#!/bin/bash

while true; do
    ping -c 2 2002:0db8:1234:a220::2 >/dev/null 2>&1 
    if [ $? -ne 0 ]; then
        /bin/bash /etc/reset_ipip1.sh
    fi
    sleep 5
done
"""
    with open("/etc/resetbasedonping1.sh", "w") as f:
        f.write(script_content)
    os.chmod("/etc/resetbasedonping1.sh", 0o755)


def reset_ping_ipip6iran1():
    script_content = f"""#!/bin/bash
while true; do
    ping -c 2 2002:0db8:1234:a220::1 >/dev/null 2>&1 
    if [ $? -ne 0 ]; then
        /bin/bash /etc/reset_ipip1.sh
    fi
    sleep 5
done
"""
    with open("/etc/resetbasedonping1.sh", "w") as f:
        f.write(script_content)
    os.chmod("/etc/resetbasedonping1.sh", 0o755)


def resetping_service_ipip1():
    service_content = """[Unit]
Description=Azumi local Service reset
After=network.target

[Service]
Type=simple
Restart=always    
LimitNOFILE=1048576
ExecStart=/etc/resetbasedonping1.sh

[Install]
WantedBy=multi-user.target
"""
    with open("/etc/systemd/system/azumireset1.service", "w") as f:
        f.write(service_content)
    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", "azumireset1"])
    subprocess.run(["systemctl", "restart", "azumireset1"])


def reset_local_ip6ip6kharej(interval):
    service_name = "ip6ip6reset1.service"

    daemon_script_content = f"""#!/bin/bash
INTERVAL={interval}

while true; do
    /bin/bash /etc/reset_ipip1.sh
    sleep $INTERVAL
done
"""

    with open("/usr/local/bin/ipip1_daemon.sh", "w") as daemon_script_file:
        daemon_script_file.write(daemon_script_content)

    subprocess.run(["chmod", "+x", "/usr/local/bin/ipip1_daemon.sh"])

    service_content = f"""[Unit]
Description=Custom Daemon

[Service]
ExecStart=/usr/local/bin/ipip1_daemon.sh
Restart=always

[Install]
WantedBy=multi-user.target
"""

    with open(f"/etc/systemd/system/{service_name}", "w") as service_file:
        service_file.write(service_content)

    ipsec_reset_script_content = """#!/bin/bash
ip link set dev azumi down   
ip link delete azumi
ip link set dev azumip down
ip link delete azumip 
/bin/bash /etc/private.sh 
ping -c 1 fd1d:fc98:b73e:b481::2
/bin/bash /etc/ipip.sh 
ping -c 1 2002:0db8:1234:a220::2
systemctl restart strong-azumi1 
"""

    with open("/etc/reset_ipip1.sh", "w") as script_file:
        script_file.write(ipsec_reset_script_content)

    subprocess.run(["chmod", "+x", "/etc/reset_ipip1.sh"])
    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", service_name])
    subprocess.run(["systemctl", "restart", service_name])


