def reset_local_menu():
    os.system("clear")
    print("\033[92m ^ ^\033[0m")
    print("\033[92m(\033[91mO,O\033[92m)\033[0m")
    print("\033[92m(   ) \033[93m Reset Local Multi Menu\033[0m")
    print('\033[92m "-"\033[93m═════════════════════════════════════════\033[0m')
    print("\033[93m╭───────────────────────────────────────╮\033[0m")
    print("\033[93mChoose what to do:\033[0m")
    print("1. \033[92mIP6IP6\033[0m")
    print("2. \033[94mIP6IP6 + IPSEC\033[0m")
    print("3. \033[93mGRE6\033[0m")
    print("4. \033[92mGRE6 + IPSEC\033[0m")
    print("5. \033[92mGRE6TAP\033[0m")
    print("6. \033[92mGRE6TAP + IPSEC\033[0m")
    print("7. \033[92m6TO4\033[0m")
    print("8. \033[93m6TO4 + IPSEC\033[0m")
