# reset
def reset_ping_private1kharej():
    script_content = f"""#!/bin/bash

while true; do
    ping -c 2 2002:801b::2 >/dev/null 2>&1 
    if [ $? -ne 0 ]; then
        /bin/bash /etc/reset_private1.sh
    fi
    sleep 5
done
"""
    with open("/etc/resetbasedonping1.sh", "w") as f:
        f.write(script_content)
    os.chmod("/etc/resetbasedonping1.sh", 0o755)


