def install_bash():
    if not os.path.isfile("/bin/bash"):
        try:
            subprocess.run(["sudo", "apt-get", "update"], check=True)
            subprocess.run(["sudo", "apt-get", "install", "-y", "bash"], check=True)
            print("\033[92mbash has been installed successfully\033[0m")
        except subprocess.CalledProcessError as e:
            print(f"\033[91mError occurred during installation: {e}\033[0m")
            return False
    else:
        print("\033[93mbash is already installed\033[0m")
        return True


def reset_ping_ipip6kharej1new():
    script_content = f"""#!/bin/bash

while true; do
    ping -c 2 2002:0db8:1234:a220::2 >/dev/null 2>&1 
    if [ $? -ne 0 ]; then
        ip link set dev azumi down
        ip link delete azumi
        ip link set dev azumip down
        ip link delete azumip
        sleep 30
        /bin/bash /etc/private.sh
        ping -c 1 fd1d:fc98:b73e:b481::2 
        /bin/bash /etc/ipip.sh 
        ping -c 1 2002:0db8:1234:a220::2
        systemctl restart strong-azumi1 
    fi
    sleep 5
done
"""
    with open("/etc/resetbasedonping1.sh", "w") as f:
        f.write(script_content)
    os.chmod("/etc/resetbasedonping1.sh", 0o755)


