def resetping_service_private10new():
    service_content = """[Unit]
Description=Azumi local Service reset
After=network.target

[Service]
Type=simple
Restart=always    
LimitNOFILE=1048576
ExecStart=/etc/resetbasedonping10.sh

[Install]
WantedBy=multi-user.target
"""
    with open("/etc/systemd/system/azumireset10.service", "w") as f:
        f.write(service_content)
    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", "azumireset10"])
    subprocess.run(["systemctl", "restart", "azumireset10"])


