def edit_l2tp_server_config1():
    if not os.geteuid() == 0:
        print("WARNING: You may need to run this script as root (sudo) to edit and reload L2TP.")
    
    current_vals = read_config(CONFIG_FILE_SERVER1)
    current_peer_ip = get_keepalive_peer_ip_server1()

    while True:
        os.system("clear")
