def vxlan_cron_job():
    try:

        subprocess.run(
            "crontab -l | grep -v '/bin/bash /usr/local/bin/bridge.sh' | crontab -",
            shell=True,
            capture_output=True,
            text=True,
        )

        subprocess.run(
            "(crontab -l ; echo '@reboot /bin/bash /usr/local/bin/bridge.sh') | crontab -",
            shell=True,
            capture_output=True,
            text=True,
        )

        display_checkmark("\033[92mCronjob added successfully!\033[0m")
    except subprocess.CalledProcessError as e:
        print("\033[91mFailed to add cronjob:\033[0m", e)


def ping_vxlan_service():
    service_content = """[Unit]
Description=keepalive
After=network.target

[Service]
ExecStart=/bin/bash /etc/ping_vxlan.sh
Restart=always

[Install]
WantedBy=multi-user.target
"""

    service_file_path = "/etc/systemd/system/ping_vxlan_service.service"
    with open(service_file_path, "w") as service_file:
        service_file.write(service_content)

    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", "ping_vxlan_service"])
    subprocess.run(["systemctl", "start", "ping_vxlan_service"])
    sleep(1)
    subprocess.run(["systemctl", "restart", "ping_vxlan_service"])


