def vxlan_mtuz1():
    mtu_value = input(
        "\033[93mEnter the \033[92mMTU value \033[93m[ \033[96mVxlan \033[93m]:\033[0m "
    )
    mtu_command = f"ip link set dev vxlan mtu {mtu_value}\n"

    if os.path.exists("/usr/local/bin/bridge.sh"):
        with open("/usr/local/bin/bridge.sh", "r") as file:
            sh_contents = file.readlines()

        mtu_exists = False
        for i in range(len(sh_contents)):
            if "link set dev vxlan mtu" in sh_contents[i]:
                sh_contents[i] = mtu_command
                mtu_exists = True
                break

        if not mtu_exists:
            sh_contents.append(mtu_command)

        with open("/usr/local/bin/bridge.sh", "w") as file:
            file.writelines(sh_contents)

        print("\033[92mMTU command edited successfully\033[0m")
        subprocess.run(mtu_command, shell=True)
    else:
        print("\033[91mCommand file doesn't exist\033[0m")


def vxlan_mtuz2():
    mtu_value_vxlan = input(
        "\033[93mEnter the \033[92mMTU value \033[93m[ \033[96mVxlan \033[93m]:\033[0m "
    )
    mtu_command_vxlan = f"ip link set dev vxlan mtu {mtu_value_vxlan}\n"

    mtu_value_bridge = input(
        "\033[93mEnter the \033[92mMTU value \033[93m[ \033[96mBridge \033[93m]:\033[0m "
    )
    mtu_command_bridge = f"ip link set dev azumibr mtu {mtu_value_bridge}\n"

    if os.path.exists("/usr/local/bin/bridge.sh"):
        with open("/usr/local/bin/bridge.sh", "r") as file:
            sh_contents = file.readlines()

        mtu_vxlan_exists = False
        mtu_bridge_exists = False
        for i in range(len(sh_contents)):
            if "link set dev vxlan mtu" in sh_contents[i]:
                sh_contents[i] = mtu_command_vxlan
                mtu_vxlan_exists = True
            elif "link set dev azumibr mtu" in sh_contents[i]:
                sh_contents[i] = mtu_command_bridge
                mtu_bridge_exists = True

        if not mtu_vxlan_exists:
            sh_contents.append(mtu_command_vxlan)
        if not mtu_bridge_exists:
            sh_contents.append(mtu_command_bridge)

        with open("/usr/local/bin/bridge.sh", "w") as file:
            file.writelines(sh_contents)

        print("\033[92mMTU commands edited successfully\033[0m")
        subprocess.run(mtu_command_vxlan, shell=True)
        subprocess.run(mtu_command_bridge, shell=True)
    else:
        print("\033[91mCommand file doesn't exist\033[0m")


