def ip4_simpk1():
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")
    local_ip = input("\033[93mEnter \033[92mkharej\033[93m IPV4 address: \033[0m")
    remote_ip = input("\033[93mEnter \033[92mIRAN\033[93m IPV4 address: \033[0m")
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")

    subprocess.run(
        [
            "sudo",
            "ip",
            "link",
            "add",
            "dev",
            "azumiespn",
            "type",
            "erspan",
            "local",
            local_ip,
            "remote",
            remote_ip,
            "seq",
            "key",
            "100",
            "erspan_ver",
            "1",
            "erspan",
            "1",
        ],
        stdout=subprocess.DEVNULL,
    )
    subprocess.run(
        ["sudo", "ip", "link", "set", "azumiespn", "up"], stdout=subprocess.DEVNULL
    )
    subprocess.run(
        ["sudo", "ip", "addr", "add", "66.200.1.1/32", "dev", "azumiespn"],
        stdout=subprocess.DEVNULL,
    )
    subprocess.run(
        ["sudo", "ip", "route", "add", "66.200.2.1/32", "dev", "azumiespn"],
        stdout=subprocess.DEVNULL,
    )

    print("\033[93m─────────────────────────────────────────────────────────\033[0m")
    display_notification("\033[93mAdding commands...\033[0m")
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")

    with open("/etc/spn.sh", "w") as f:
        f.write(
            f"sudo ip link add dev azumiespn type erspan local {local_ip} remote {remote_ip} seq key 100 erspan_ver 1 erspan 1\n"
        )
        f.write("sudo ip link set azumiespn up\n")
        f.write("sudo ip addr add 66.200.1.1/32 dev azumiespn\n")
        f.write("sudo ip route add 66.200.2.1/32 dev azumiespn\n")

    set_mtu = input(
        "\033[93mDo you want to set the \033[92mMTU\033[96m [Erspan]\033[93m? (\033[92myes\033[93m/\033[91mno\033[93m): \033[0m"
    )

    if set_mtu.lower() == "yes" or set_mtu.lower() == "y":
        mtu_value = input(
            "\033[93mEnter the desired\033[92m MTU value\033[93m: \033[0m"
        )
        mtu_command = f"ip link set dev azumiespn mtu {mtu_value}\n"
        with open("/etc/spn.sh", "a") as f:
            f.write(mtu_command)
        subprocess.run(mtu_command, shell=True, check=True)
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")
    display_checkmark("\033[92mConfiguration is done!\033[0m")

    espan_job()

    time.sleep(1)
    display_checkmark("\033[92mkeepalive service Configured!\033[0m")

    espan_ping()
    time.sleep(1)
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")
    print("\033[93mCreated IP Addresses (Kharej):\033[0m")
    print("\033[92m" + "+---------------------------+" + "\033[0m")
    print("\033[92m" + "       66.200.1.1\033[0m")
    print("\033[92m" + "+---------------------------+" + "\033[0m")

    script_content = """#!/bin/bash
ip_address="66.200.2.1"
max_pings=5
interval=2
while true
do
    for ((i = 1; i <= max_pings; i++))
    do
        ping_result=$(ping -c 1 $ip_address | grep "time=" | awk -F "time=" "{print $2}" | awk -F " " "{print $1}" | cut -d "." -f1)
        if [ -n "$ping_result" ]; then
            echo "Ping successful! Response time: $ping_result ms"
        else
            echo "Ping failed!"
        fi
    done
    echo "Waiting for $interval seconds..."
    sleep $interval
done
"""

    with open("/etc/ping_espan.sh", "w") as script_file:
        script_file.write(script_content)

    os.chmod("/etc/ping_espan.sh", 0o755)
    ping_gengre_service()

    print("\033[92mKharej Server Configuration Completed!\033[0m")


