    local_ip = "2002:831b::2"  # iran ip
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")
    num_additional_ips = int(
        input(
            "\033[97mEnter the number of \033[92madditional IPs\033[97m for the \033[92mGRE6\033[97m tunnel: "
        )
    )
    gre64_iran2_tunnel(remote_ip, local_ip, num_additional_ips)

    ip_address = "2002:831a::1"  # kharejip
    max_pings = 3
    interval = 2
    iran_ping4_script(ip_address, max_pings, interval)
    print("\033[92m(\033[96mPlease wait,Azumi is pinging...\033[0m")
    ping_result = subprocess.run(
        ["ping6", "-c", "2", ip_address], capture_output=True, text=True
    ).stdout.strip()
    print(ping_result)

    iran_gre64_service()

    gre64_cronjob()


