def ip6_ir_ipsec():
    os.system("clear")
    print("\033[92m ^ ^\033[0m")
    print("\033[92m(\033[91mO,O\033[92m)\033[0m")
    print(
        "\033[92m(   ) \033[93mIP6IP6 + IPSec \033[92m[5]IRAN\033[96m [1]Kharej\033[93m Menu\033[0m"
    )
    print('\033[92m "-"\033[93m══════════════════════════\033[0m')
    print("\033[93m╭───────────────────────────────────────╮\033[0m")
    print("\033[93mChoose what to do:\033[0m")
    print("1. \033[92mIRAN[1]\033[0m")
    print("2. \033[92mIRAN[2]\033[0m")
    print("3. \033[93mIRAN[3]\033[0m")
    print("4. \033[92mIRAN[4]\033[0m")
    print("5. \033[92mIRAN[5]\033[0m")
    print("\033[93m───────────────────────────────────────\033[0m")
    print("6. \033[93mKharej\033[0m")
    print("0. \033[94mback to the previous menu\033[0m")
    print("\033[93m╰───────────────────────────────────────╯\033[0m")

    while True:
        server_type = input("\033[38;5;205mEnter your choice Please: \033[0m")
        if server_type == "1":
            ipip6_reset_rmvmnu()
            remove_config()
            enable_reset_ipsec()
            iran2_ipip61sec_menu()
            restart_forced_strongazumi()
            break
        elif server_type == "2":
            ipip6_reset_rmvmnu()
            remove_config()
            enable_reset_ipsec()
            iran2_ipip62sec_menu()
            restart_forced_strongazumi()
            break
        elif server_type == "3":
            ipip6_reset_rmvmnu()
            remove_config()
            enable_reset_ipsec()
            iran2_ipip63sec_menu()
            restart_forced_strongazumi()
            break
        elif server_type == "4":
            ipip6_reset_rmvmnu()
            remove_config()
            enable_reset_ipsec()
            iran2_ipip64sec_menu()
            restart_forced_strongazumi()
            break
        elif server_type == "5":
            ipip6_reset_rmvmnu()
            remove_config()
            enable_reset_ipsec()
            iran2_ipip65sec_menu()
            restart_forced_strongazumi()
            break
        elif server_type == "6":
            ipip6_reset_rmvmnu()
            enable_reset_ipsec()
            iranip_qsec()
            break
        elif server_type == "0":
            os.system("clear")
            ip6_mnu_ipsec()
            break
        else:
            print("Invalid choice.")


