## original mtu
def mtu_menu():
    os.system("clear")
    print("\033[92m ^ ^\033[0m")
    print("\033[92m(\033[91mO,O\033[92m)\033[0m")
    print("\033[92m(   ) \033[93mEdit MTU Menu\033[0m")
    print('\033[92m "-"\033[93m══════════════════════════\033[0m')
    print("\033[93m╭───────────────────────────────────────╮\033[0m")
    print("\033[93mChoose what to do:\033[0m")
    print("1. \033[92mPrivate IP\033[0m")
    print("2. \033[93mIP6IP6 \033[0m")
    print("3. \033[96mGRE \033[0m")
    print("4. \033[92mGRE6 \033[0m")
    print("5. \033[92mGRE6tap \033[0m")
    print("6. \033[93m6to4 \033[0m")
    print("7. \033[96m6to4 anycast \033[0m")
    print("8. \033[92mGeneve \033[0m")
    print("9. \033[93mErspan \033[0m")
    print("10. \033[92mVxlan [IPsec too] \033[0m")
    print("0. \033[94mback to the previous menu\033[0m")
    print("\033[93m╰───────────────────────────────────────╯\033[0m")

    while True:
        server_type = input("\033[38;5;205mEnter your choice Please: \033[0m")
        if server_type == "1":
            private_mtu()
            break
        elif server_type == "2":
            ipip_mtu()
            break
        elif server_type == "3":
            gre_mtu()
            break
        elif server_type == "4":
            gre6_mtu()
            break
        elif server_type == "5":
            gre6tap_mtu()
            break
        elif server_type == "6":
            i6to4_mtu()
            break
        elif server_type == "7":
            i6to4any_mtu()
            break
        elif server_type == "8":
            gen_mtu()
            break
        elif server_type == "9":
            erspan_mtu()
            break
        elif server_type == "10":
            vxlan_mtu()
            break
        elif server_type == "0":
            clear()
            singleserver_mnu()
            break
        else:
            print("Invalid choice.")


