# isata
# import os
import re
import subprocess
import time
import sys


def ipsec_statuscheck(service_name):
    try:
        status = (
            subprocess.check_output(f"systemctl is-active {service_name}", shell=True)
            .decode("utf-8")
            .strip()
        )
        return status == "active"
    except subprocess.CalledProcessError:
        return False


def check_global(interface):
    try:
        output = subprocess.check_output(
            f"ip -6 addr show {interface}", shell=True
        ).decode("utf-8")
        inet6_addresses = re.findall(
            r"inet6 (2001:db8::5efe:[\da-fA-F:]+)/64 scope global", output
        )
        return inet6_addresses if inet6_addresses else None
    except subprocess.CalledProcessError:
        return None


def isatap_status():
    os.system("clear")
    print("\033[92m ^ ^\033[0m")
    print("\033[92m(\033[91mO,O\033[92m)\033[0m")
    print("\033[92m(   ) \033[93mISATAP Status Menu\033[0m")
    print('\033[92m "-"\033[93m══════════════════════════\033[0m')
    print("\033[93m╭─────────────────────────────────────────────────╮\033[0m")
    print("\033[93mYou are viewing the status of your current tunnel:\033[0m")
    print("\033[93m────────────────────────────────────────\033[0m")

    interfaces = ["azumiserver", "azumiclient"]
    active_int = []
    for interface in interfaces:
        if interface_ex(interface):
            status = interface_check(interface)
            if status:
                active_int.append(interface)

    if not active_int:
        print(" No Interfaces available.")
    elif "azumiserver" in active_int:
        with open("/etc/port.sh", "r") as file:
            contents = file.read()

        print(
            " \033[97mServer \033[93mStatus: \033[92mOnline\033[97m | \033[93mInterface name:\033[96m azumiserver\033[0m"
        )
        print(" \033[93mTunnel Method: \033[97mISATAP\033[0m")

        ipsec_status = ipsec_statuscheck("strong-azumi1")
        if ipsec_status:
            print(" \033[93mIPsec Status: \033[92mActive\033[0m")
        else:
            print(" \033[93mIPsec Status: \033[91mInactive\033[0m")
        print("\033[93m────────────────────────────────────────\033[0m")
        inet6_addresses = check_global("azumiserver")
        if inet6_addresses:
            for addr in inet6_addresses:
                print(f" \033[93mPrivate IPV6 address: \033[97m{addr}\033[0m")
        else:
            print(" \033[91mServer has no IPV6 address\033[0m")

        remote_ips = re.findall(r"REMOTE_IPV4_(\d+)=(\S+)", contents)
        if remote_ips:
            for idx, ip in remote_ips:
                print(f" \033[93mClient IP \033[96m{idx}\033[93m: \033[97m{ip}\033[0m")
        else:
            print(" \033[91mNo remote IP found\033[0m")

    elif "azumiclient" in active_int:
        with open("/etc/port.sh", "r") as file:
            contents = file.read()

        client_displayed = False
        for i in range(1, 6):
            server_file = f"/etc/server{i}.sh"
            if os.path.exists(server_file):
                print(
                    f" \033[97mClient \033[96m{i}\033[93m Status: \033[92mOnline\033[97m | \033[93mInterface name:\033[96m azumiclient\033[0m"
                )
                client_displayed = True

        if not client_displayed:
            print(
                " \033[97mClient\033[93m Status: \033[92mOnline\033[97m | \033[93mInterface name:\033[96m azumiclient\033[0m"
            )

        print(" \033[93mTunnel Method: \033[97mISATAP\033[0m")

        ipsec_status = ipsec_statuscheck("strong-azumi1")
        if ipsec_status:
            print(" \033[93mIPsec Status: \033[92mActive\033[0m")
        else:
            print(" \033[93mIPsec Status: \033[91mInactive\033[0m")
        print("\033[93m────────────────────────────────────────\033[0m")
        inet6_addresses = check_global("azumiclient")
        if inet6_addresses:
            for addr in inet6_addresses:
                print(f" \033[93mPrivate IPV6 address: \033[97m{addr}\033[0m")
        else:
            print(" \033[91mClient has no IPV6 address\033[0m")

        remote_ips = re.findall(r"REMOTE_IPV4=(\S+)", contents)
        if remote_ips:
            for ip in remote_ips:
                print(f" \033[93mServer IP : \033[97m{ip}\033[0m")
        else:
            print(" \033[91mNo remote IP found\033[0m")

    print("\033[93m────────────────────────────────────────\033[0m")
    secret_key = ipsec_secret()
    if secret_key != "Not found":
        print(" \033[93mIPsec Secret Key:\033[96m", secret_key, "\033[0m")
    else:
        print(" \033[93mIPSEC is not available\033[0m")
    print("\033[93m─────────────────────────────────────────────────\033[0m")
    print("0. \033[94mback to the previous menu\033[0m")
    print("\033[93m╰─────────────────────────────────────────────────╯\033[0m")

    while True:
        choice = input("\033[38;5;205mEnter your choice Please: \033[0m")
        if choice == "0":
            os.system("clear")
            isatap_mnu()
            break
        else:
            print("Invalid choice.")


