def client_isatap_rmvmnu():
    delete_cron3()
    delete_cron4()
    ipsec_service_remove()
    print("\033[93m───────────────────────────────────────\033[0m")
    display_notification(
        "\033[93mRemoving ISATAP + \033[92mIpsec \033[93mClient\033[0m"
    )
    print("\033[93m───────────────────────────────────────\033[0m")

    try:
        devnull = open(os.devnull, "w")
        display_notification("\033[93mRemoving cronjob & other stuff...\033[0m")

        commands = [
            'crontab -l | grep -v "@reboot /bin/bash /usr/local/bin/isatap.sh" | crontab -',
            "sudo rm /etc/ipsec1.conf",
            "sudo rm /etc/ipsec2.sh",
            "sudo rm /etc/server1.sh",
            "sudo rm /etc/server2.sh",
            "sudo rm /etc/server3.sh",
            "sudo rm /etc/server4.sh",
            "sudo rm /etc/server5.sh",
            "sudo rm /usr/local/bin/ping_keepalive.sh",
            "sudo rm /etc/ipsec.secrets",
            "sudo rm /usr/bin/local/isatap.sh",
            "sudo rm /etc/resetbasedonping1.sh",
            "systemctl disable azumireset1",
            "systemctl stop azumireset1",
            "sudo rm /etc/systemd/system/azumireset1.service",
            "systemctl disable isatapreset",
            "systemctl stop isatapreset",
            "sudo rm /etc/systemd/system/isatapreset.service",
            "sudo rm /etc/reset_isatap.sh",
            "sudo rm /usr/local/bin/isatap_daemon.sh",
            "systemctl disable isa",
            "systemctl stop isa",
            "sudo rm /etc/systemd/system/isa.service",
            "systemctl disable radvd",
            "systemctl stop radvd",
            "systemctl disable strong-azumi1",
            "systemctl stop strong-azumi1",
            "sudo rm /etc/systemd/system/strong-azumi1.service",
            "ip link set dev azumiclient down",
            "ip link delete azumiclient",
            "ip link delete sit0",
            "systemctl daemon-reload",
        ]

        for command in commands:
            subprocess.run(command, shell=True, stdout=devnull, stderr=devnull)

        hide("apt purge strongswan -y")
        hide("apt purge radvd -y")

        ports = []
        if os.path.exists("/etc/port.sh"):
            with open("/etc/port.sh", "r") as f:
                content = f.read().strip()
                for line in content.split("\n"):
                    if line.startswith("PORT="):
                        ports.append(line.split("=")[1])

        for port in ports:
            subprocess.run(f"sudo ufw delete allow {port}", shell=True)

        devnull.close()

        print("Progress: ", end="")
        frames = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]
        delay = 0.1
        duration = 1
        end_time = time.time() + duration

        while time.time() < end_time:
            for frame in frames:
                print("\r[%s] Loading...  " % frame, end="")
                time.sleep(delay)
                print("\r[%s]             " % frame, end="")
                time.sleep(delay)

        display_checkmark("\033[92mUninstall completed!\033[0m")
    except subprocess.CalledProcessError as e:
        print("Error:", e.output.decode().strip())
    except Exception as e:
        print("Error:", str(e))


