def animate(message):
    for char in message:
        print(char, end="", flush=True)
        time.sleep(0.05)
    print()


def anime():
    animation = [
        "[=     ]",
        "[==    ]",
        "[===   ]",
        "[====  ]",
        "[===== ]",
        "[======]",
        "[===== ]",
        "[====  ]",
        "[===   ]",
        "[==    ]",
        "[=     ]",
    ]
    for i in range(20):
        time.sleep(0.1)
        sys.stdout.write(f"\r{animation[i % len(animation)]}")
        sys.stdout.flush()
    sys.stdout.write("\r")
    sys.stdout.flush()


def hide(command):
    process = subprocess.Popen(
        command, shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE
    )
    while process.poll() is None:
        anime()
    _, stderr = process.communicate()
    if process.returncode != 0:
        print(f"\033[91merror: {stderr.decode()}\033[0m")


def forward():
    with open("/proc/sys/net/ipv4/ip_forward", "r") as f:
        ipv4_forwarding = f.read().strip()

    with open("/proc/sys/net/ipv6/conf/all/forwarding", "r") as f:
        ipv6_forwarding = f.read().strip()

    if ipv4_forwarding == "0":
        display_notification("\033[93mEnabling IPv4 forwarding..\033[0m")
        os.system("echo 1 > /proc/sys/net/ipv4/ip_forward")
    else:
        print("\033[93mIPv4 forwarding is already enabled\033[0m")

    if ipv6_forwarding == "0":
        display_notification("\033[93mEnabling IPv6 forwarding..\033[0m")
        os.system("echo 1 > /proc/sys/net/ipv6/conf/all/forwarding")
    else:
        print("\033[93mIPv6 forwarding is already enabled\033[0m")


def isa_cronjob():
    try:
        subprocess.run(
            "crontab -l | grep -v '/usr/local/bin/isatap.sh' | crontab -",
            shell=True,
            capture_output=True,
            text=True,
        )
        subprocess.run(
            "(crontab -l ; echo '@reboot /bin/bash /usr/local/bin/isatap.sh') | crontab -",
            shell=True,
            capture_output=True,
            text=True,
        )
        display_checkmark("\033[92mCronjob added successfully!\033[0m")
    except subprocess.CalledProcessError as e:
        print("\033[91mFailed to add cronjob:\033[0m", e)


def create_isatap_client(local_ipv4, remote_ipv4):
    client_path = "/usr/local/bin/isatap.sh"
    mtu_command = ""
    set_mtu = input(
        "\033[93mDo you want to set MTU? (\033[92myes\033[93m/\033[91mno\033[93m): \033[0m"
    ).lower()
    if set_mtu in ["yes", "y"]:
        mtu_value = input("\033[93mEnter the MTU value: \033[0m")
        mtu_command = f"ip link set dev azumiclient mtu {mtu_value}\n"

    script_content = f"""#!/bin/bash

ip tunnel add azumiclient mode isatap local {local_ipv4} remote {remote_ipv4} ttl 64
ip link set azumiclient up
ip addr add 2001:db8::5efe:{local_ipv4}/64 dev azumiclient
{mtu_command}
"""

    with open(client_path, "w") as file:
        file.write(script_content)

    subprocess.run(["chmod", "+x", client_path], check=True)
    subprocess.run(["bash", client_path], check=True)


