def load_balance(server_ipv6, iran_servers):
    file_path = "/usr/local/bin/isatap.sh"
    lb_script = "\n\n# Azumi at your service\n"

    for i, (client_ip, port) in enumerate(iran_servers, start=1):
        lb_script += f"""
ipvsadm -A -t [{server_ipv6}]:{port} -s wrr
ipvsadm -a -t [{server_ipv6}]:{port} -r [{client_ip}]:{port} -g
"""

    with open(file_path, "a") as file:
        file.write(lb_script)


