def reset_ping_isatapclient(client_ipv6_list):
    ping_commands = "\n".join(
        [f"    ping -c 2 {ipv6} >/dev/null 2>&1" for ipv6 in client_ipv6_list]
    )
    script_content = f"""#!/bin/bash

while true; do
{ping_commands}
    if [ $? -ne 0 ]; then
        /bin/bash /etc/reset_isatap.sh
    fi
    sleep 5
done
"""
    with open("/etc/resetbasedonping1.sh", "w") as f:
        f.write(script_content)
    os.chmod("/etc/resetbasedonping1.sh", 0o755)


def resetping_service_isatap():
    service_content = """[Unit]
Description=Azumi local Service reset
After=network.target

[Service]
Type=simple
Restart=always    
LimitNOFILE=1048576
ExecStart=/etc/resetbasedonping1.sh

[Install]
WantedBy=multi-user.target
"""
    with open("/etc/systemd/system/azumireset1.service", "w") as f:
        f.write(service_content)
    subprocess.run(["systemctl", "daemon-reload"])
    subprocess.run(["systemctl", "enable", "azumireset1"])
    subprocess.run(["systemctl", "restart", "azumireset1"])


