def reset_ping_isatapserver(server_ipv6):
    script_content = f"""#!/bin/bash

while true; do
    ping -c 2 {server_ipv6} >/dev/null 2>&1 
    if [ $? -ne 0 ]; then
        /bin/bash /etc/reset_isatap.sh
    fi
    sleep 5
done
"""
    with open("/etc/resetbasedonping1.sh", "w") as f:
        f.write(script_content)
    os.chmod("/etc/resetbasedonping1.sh", 0o755)


