    remote_subnet = input("\033[93mEnter \033[92mkharej\033[93m Subnet: \033[0m")
    ufw(local_ip)
    ufw(remote_ip)
    ufw("66.200.2.1")
    ufw("66.200.1.1")
    psk = input("\033[93mEnter the \033[92mSecret key\033[93m: \033[0m")

    config_strongsw_simi1(local_ip, local_subnet, remote_ip, remote_subnet, psk)

    subprocess.run(
        [
            "sudo",
            "ip",
            "link",
            "add",
            "name",
            "azumigen",
            "type",
            "geneve",
            "id",
            "1000",
            "remote",
            remote_ip,
        ],
        stdout=subprocess.DEVNULL,
    )
    subprocess.run(
        ["sudo", "ip", "link", "set", "azumigen", "up"], stdout=subprocess.DEVNULL
    )
    subprocess.run(
        ["sudo", "ip", "addr", "add", "66.200.2.1/32", "dev", "azumigen"],
        stdout=subprocess.DEVNULL,
    )
    subprocess.run(
        ["sudo", "ip", "route", "add", "66.200.1.1/32", "dev", "azumigen"],
        stdout=subprocess.DEVNULL,
    )

    print("\033[93m─────────────────────────────────────────────────────────\033[0m")
    display_notification("\033[93mAdding commands...\033[0m")
    print("\033[93m─────────────────────────────────────────────────────────\033[0m")

    with open("/etc/spn.sh", "w") as f:
        f.write(
            f"sudo ip link add name azumigen type geneve id 1000 remote {remote_ip}\n"
        )
        f.write("sudo ip link set azumigen up\n")
        f.write("sudo ip addr add 66.200.2.1/32 dev azumigen\n")
        f.write("sudo ip route add 66.200.1.1/32 dev azumigen\n")
